{
    "name": "task/llm-billing-assignment",
    "description": "Тестовое задание: учёт расходов на LLM-токены",
    "type": "project",
    "license": "proprietary",
    "require": {
        "doctrine/doctrine-bundle": "^3.2",
        "doctrine/doctrine-migrations-bundle": "^3.3",
        "doctrine/orm": "^3.3",
        "ext-bcmath": "*",
        "ext-ctype": "*",
        "ext-iconv": "*",
        "php": ">=8.4",
        "symfony/console": "^8.0",
        "symfony/dotenv": "^8.0",
        "symfony/framework-bundle": "^8.0",
        "symfony/runtime": "^8.0",
        "symfony/var-exporter": "^8.0",
        "symfony/yaml": "^8.0"
    },
    "require-dev": {
        "phpunit/phpunit": "^11.5",
        "squizlabs/php_codesniffer": "^3.13",
        "vimeo/psalm": "^6.0"
    },
    "autoload": {
        "psr-4": {
            "App\\": "src/"
        }
    },
    "autoload-dev": {
        "psr-4": {
            "App\\Tests\\": "tests/"
        }
    },
    "config": {
        "sort-packages": true,
        "allow-plugins": {
            "symfony/runtime": true
        }
    }
}
# Учёт расходов на LLM-токены

Тестовое задание — см. `TASK.md`. Каркас приложения: PHP 8.4+, Symfony,
Doctrine ORM, PostgreSQL 17.

## Быстрый старт

```bash
cp .env.example .env
make db-up     # PostgreSQL 17 в docker (порт 5544), ждёт готовности
make migrate   # создать БД и накатить миграции
bin/console    # список команд
```

Пример данных для самопроверки — в `fixtures/` (используется в разделе
«Пример расчёта» задания).

Тесты: `make test` (PHPUnit уже в `vendor/`).
COMPOSE = docker compose

.PHONY: db-up db-down migrate console test help

db-up: ## Поднять PostgreSQL 17 (порт из .env, по умолчанию 5544)
	$(COMPOSE) up -d
	@until $(COMPOSE) exec -T db pg_isready -U app -d app >/dev/null 2>&1; do sleep 1; done
	@echo "PostgreSQL готов"

db-down: ## Остановить PostgreSQL
	$(COMPOSE) down

migrate: ## Создать БД (если нет) и накатить миграции
	bin/console doctrine:database:create --if-not-exists
	bin/console doctrine:migrations:migrate -n

console: ## Открыть список команд
	bin/console

test: ## PHPUnit
	vendor/bin/phpunit

help: ## Показать справку
	@grep -E '^[a-zA-Z_-]+:.*?## ' $(MAKEFILE_LIST) | awk 'BEGIN {FS = ":.*?## "}; {printf "  make %-10s %s\n", $$1, $$2}'
services:
  db:
    image: postgres:17-alpine
    environment:
      POSTGRES_USER: app
      POSTGRES_PASSWORD: app
      POSTGRES_DB: app
    ports:
      - "127.0.0.1:${BILLING_PG_PORT:-5544}:5432"
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U app -d app"]
      interval: 2s
      timeout: 2s
      retries: 30
APP_ENV=dev
APP_DEBUG=1
APP_SECRET=change-me-in-local-env
DATABASE_URL=postgresql://app:app@127.0.0.1:5544/app?serverVersion=17&charset=utf8
BILLING_PG_PORT=5544
#!/usr/bin/env php
<?php

use App\Kernel;
use Symfony\Bundle\FrameworkBundle\Console\Application;

if (!is_dir(dirname(__DIR__).'/vendor')) {
    throw new LogicException('Dependencies are missing. Try running "composer install".');
}

require dirname(__DIR__).'/vendor/autoload_runtime.php';

return function (array $context) {
    $kernel = new Kernel($context['APP_ENV'] ?? 'dev', (bool) ($context['APP_DEBUG'] ?? true));

    return new Application($kernel);
};
doctrine_migrations:
    migrations_paths:
        'DoctrineMigrations': '%kernel.project_dir%/migrations'
    enable_profiler: false
parameters:
    env(DATABASE_URL): 'postgresql://app:app@127.0.0.1:5544/app?serverVersion=17&charset=utf8'

doctrine:
    dbal:
        url: '%env(resolve:DATABASE_URL)%'
        server_version: '17'
    orm:
        auto_mapping: true
        naming_strategy: doctrine.orm.naming_strategy.underscore_number_aware
        controller_resolver:
            auto_mapping: false
        mappings:
            App:
                type: attribute
                is_bundle: false
                dir: '%kernel.project_dir%/src'
                prefix: 'App'
                alias: App
framework:
    secret: '%env(APP_SECRET)%'
    php_errors:
        log: true
